 32	  appName: "Binden",
 33	  baseURL: config.BETTER_AUTH_URL,
 34	  secret: config.BETTER_AUTH_SECRET,
 35	  database: drizzleAdapter(db, { provider: "pg", schema }),
 36	  socialProviders: {
