 92	export async function getReviewAccess(headers: Headers) {
 93	  let stage = "session";
 94	  try {
 95	    const session = await auth.api.getSession({ headers });
 96	    if (!session) return { status: "signed-out" } as const;
 97	    stage = "account";
 98	    const [account] = await db
 99	      .select()
100	      .from(schema.account)
101	      .where(
102	        and(eq(schema.account.userId, session.user.id), eq(schema.account.providerId, "google")),
103	      );
104	    if (!account) throw new WorkspaceUnavailable(true);
105	    stage = "access-token";
106	    const token = await auth.api.getAccessToken({ headers, body: { accountId: account.id } });
107	    if (
108	      !token.accessToken ||
109	      (token.accessTokenExpiresAt && new Date(token.accessTokenExpiresAt).getTime() <= Date.now())
110	    )
111	      throw new WorkspaceUnavailable(true);
112	    stage = "workspace-profile";
113	    const profile = await readWorkspaceProfile(token.accessToken, account.accountId, true);
114	    stage = "reviewer-role";
115	    if (!(await hasReviewerRole(token.accessToken, profile.id, config.GOOGLE_REVIEWER_ROLE_ID)))
116	      return { status: "denied" } as const;
117	    return { status: "available", profile } as const;
118	  } catch (error) {
119	    const status =
120	      error instanceof WorkspaceUnavailable && error.reconnect ? "reconnect" : "unavailable";
121	    console.error("[review-access] Access check failed", { stage, status });
122	    return {
123	      status,
124	    } as const;
125	  }
126	}
