  9	const identitySchema = z.object({
 10	  sub: z.string().min(1).max(255),
 11	  hd: z.string().min(1),
 12	  email: z.email(),
 13	  email_verified: z.literal(true),
 14	});
 15	
 16	const profileSchema = z.object({
 17	  id: z.string().min(1),
 18	  primaryEmail: z.email(),
 19	  name: z.object({ fullName: z.string() }).optional(),
 20	  thumbnailPhotoUrl: z.url().optional(),
 21	});
 22	
 23	const roleAssignmentsSchema = z.object({
 24	  items: z.array(z.object({ roleId: z.string() })).optional(),
 25	  nextPageToken: z.string().optional(),
 26	});
 27	
 28	export class WorkspaceUnavailable extends Error {
 29	  constructor(public readonly reconnect = false) {
 30	    super(reconnect ? "Reconnect your Google account" : "Workspace unavailable");
 31	  }
 32	}
 33	
 34	export function validateIdentity(input: unknown) {
 35	  const identity = identitySchema.parse(input);
 36	  if (!process.env.GOOGLE_WORKSPACE_DOMAIN || identity.hd !== process.env.GOOGLE_WORKSPACE_DOMAIN)
 37	    throw new WorkspaceUnavailable(true);
 38	  return identity;
 39	}
 40	
 41	async function googleGet(url: string, accessToken: string) {
 42	  const response = await fetch(url, {
 43	    headers: { Authorization: `Bearer ${accessToken}` },
 44	    cache: "no-store",
 45	    signal: AbortSignal.timeout(10_000),
 46	  });
 47	  if (!response.ok) {
 48	    await logGoogleFailure(url, response);
 49	    throw new WorkspaceUnavailable(response.status === 401);
 50	  }
 51	  return response.json();
 52	}
 53	
 54	async function logGoogleFailure(url: string | URL, response: Response) {
 55	  const parsed = z
 56	    .object({
 57	      error: z.object({
 58	        errors: z
 59	          .array(
 60	            z.object({
 61	              reason: z
 62	                .string()
 63	                .regex(/^[\w.]+$/)
 64	                .max(100),
 65	            }),
 66	          )
 67	          .optional(),
 68	      }),
 69	    })
 70	    .safeParse(await response.json().catch(() => null));
 71	  console.error("[workspace] Google API rejected request", {
 72	    endpoint: new URL(url).pathname.replace(/\/users\/[^/]+/, "/users/{userKey}"),
 73	    status: response.status,
 74	    reasons: parsed.success ? parsed.data.error.errors?.map(({ reason }) => reason) : undefined,
 75	  });
 76	}
 77	
 78	export async function readWorkspaceProfile(
 79	  accessToken: string,
 80	  subject: string,
 81	  allowInitialBinding = false,
 82	) {
 83	  const identity = validateIdentity(
 84	    await googleGet("https://openidconnect.googleapis.com/v1/userinfo", accessToken),
 85	  );
 86	  if (identity.sub !== subject) throw new WorkspaceUnavailable(true);
 87	
 88	  const [binding] = await db
 89	    .select()
 90	    .from(workspaceIdentity)
 91	    .where(eq(workspaceIdentity.googleSubject, subject));
 92	  if (!binding && !allowInitialBinding) throw new WorkspaceUnavailable(true);
 93	
 94	  const url = new URL(
 95	    `https://admin.googleapis.com/admin/directory/v1/users/${encodeURIComponent(binding?.directoryId ?? identity.email)}`,
 96	  );
 97	  url.searchParams.set("viewType", "domain_public");
 98	  url.searchParams.set("fields", "id,primaryEmail,name(fullName),thumbnailPhotoUrl");
 99	  const profile = profileSchema.parse(await googleGet(url.toString(), accessToken));
100	  if (
101	    profile.primaryEmail.toLowerCase() !== identity.email.toLowerCase() ||
102	    (binding && profile.id !== binding.directoryId)
103	  )
104	    throw new WorkspaceUnavailable(true);
105	
106	  if (!binding) {
107	    await db
108	      .insert(workspaceIdentity)
109	      .values({ googleSubject: subject, directoryId: profile.id })
110	      .onConflictDoNothing();
111	    const [saved] = await db
112	      .select()
113	      .from(workspaceIdentity)
114	      .where(eq(workspaceIdentity.googleSubject, subject));
115	    if (saved?.directoryId !== profile.id) throw new WorkspaceUnavailable(true);
116	  }
117	  return profile;
118	}
119	
120	export async function hasReviewerRole(accessToken: string, directoryId: string, roleId: string) {
121	  const url = new URL(
122	    "https://admin.googleapis.com/admin/directory/v1/customer/my_customer/roleassignments",
123	  );
124	  url.searchParams.set("userKey", directoryId);
125	  url.searchParams.set("includeIndirectRoleAssignments", "true");
126	  let pageToken: string | undefined;
127	  do {
128	    const response = await fetch(url, {
129	      headers: { Authorization: `Bearer ${accessToken}` },
130	      cache: "no-store",
131	      signal: AbortSignal.timeout(10_000),
132	    });
133	    if (!response.ok) {
134	      await logGoogleFailure(url, response);
135	      if (response.status === 403) return false;
136	      throw new WorkspaceUnavailable(response.status === 401);
137	    }
138	    const assignments = roleAssignmentsSchema.parse(await response.json());
139	    if (assignments.items?.some((item) => item.roleId === roleId)) return true;
140	    pageToken = assignments.nextPageToken;
141	    if (pageToken) url.searchParams.set("pageToken", pageToken);
142	  } while (pageToken);
143	  return false;
144	}
