  3	import { auth } from "@/lib/auth";
  4	
  5	const signInBody = z.strictObject({
  6	  provider: z.literal("google"),
  7	  callbackURL: z.string().optional(),
  8	  errorCallbackURL: z.string().optional(),
  9	});
 10	
 11	async function handle(request: Request) {
 12	  const path = new URL(request.url).pathname;
 13	  const allowed =
 14	    request.method === "GET"
 15	      ? ["/api/auth/callback/google", "/api/auth/get-session"].includes(path)
 16	      : request.method === "POST" &&
 17	        ["/api/auth/sign-in/social", "/api/auth/sign-out"].includes(path);
 18	  if (!allowed) return new Response(null, { status: 404 });
 19	  if (
 20	    request.method === "POST" &&
 21	    request.headers.get("origin") !== new URL(process.env.BETTER_AUTH_URL!).origin
 22	  )
 23	    return new Response(null, { status: 403 });
 24	  if (path === "/api/auth/sign-in/social") {
 25	    try {
 26	      signInBody.parse(await request.clone().json());
 27	    } catch {
 28	      return new Response(null, { status: 400 });
 29	    }
 30	  }
 31	  const response = await auth.handler(request);
 32	  response.headers.set("Cache-Control", "no-store");
 33	  return response;
 34	}
 35	
 36	export const GET = handle;
 37	export const POST = handle;
